def fit_headings(fig):
    minimum_heights = {ax: getattr(ax, "_graphunslopify_heading_height", ax.bbox.height)
                       for ax in fig.axes if ax.get_visible()}
    for attempt in range(8):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        candidates = [(text, fig.bbox.width * 0.94, False) for text in fig.texts
                      if getattr(text, "_graphunslopify_text_target", {}).get("role") == "title"]
        for ax in fig.axes:
            if not ax.get_visible():
                continue
            candidates.extend((text, ax.bbox.width * 0.98, False)
                              for text in (ax.title, ax._left_title, ax._right_title))
            if ax.axison:
                # Axis wording may use free margins beyond the data rectangle.
                available_height = max(ax.bbox.height, minimum_heights[ax])
                grid = ax.get_subplotspec()
                if grid is not None:
                    rows = grid.get_gridspec().nrows
                    bottom = fig.bbox.y0 + fig.bbox.height * (1 - grid.rowspan.stop / rows)
                    top = fig.bbox.y0 + fig.bbox.height * (1 - grid.rowspan.start / rows)
                    center = ax.yaxis.label.get_transform().transform(ax.yaxis.label.get_position())[1]
                    available_height = max(available_height, 2 * min(center - bottom, top - center))
                candidates.extend([(ax.xaxis.label, ax.bbox.width * 0.98, False),
                                   (ax.yaxis.label, available_height * 0.98, True)])
        changed = False
        for artist, width, vertical in candidates:
            target = getattr(artist, "_graphunslopify_text_target", {})
            if target.get("role") not in {"title", "panel_title", "axis_label", "metric_label"}:
                continue
            if not artist.get_visible() or not artist.get_text().strip() or width <= 0:
                continue
            box = artist.get_window_extent(renderer)
            if (box.height if vertical else box.width) <= width:
                continue
            original = getattr(artist, "_graphunslopify_heading_original", artist.get_text())
            wrapped = wrap_heading(original, artist, renderer, width)
            if wrapped != artist.get_text():
                artist._graphunslopify_heading_original = original
                artist.set_text(wrapped)
                changed = True
        if not changed:
            return
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        row_heights = {}
        for ax, minimum in minimum_heights.items():
            grid = ax.get_subplotspec()
            if grid is None:
                continue
            ax._graphunslopify_heading_height = minimum
            box = ax.get_tightbbox(renderer)
            if box is None:
                continue
            height = minimum + max(0, box.y1 - ax.bbox.y1) + max(0, ax.bbox.y0 - box.y0)
            rows = list(grid.rowspan)
            for row in rows:
                row_heights[row] = max(row_heights.get(row, 0), height / len(rows))
        title_height = max((text.get_window_extent(renderer).height for text in fig.texts
                            if text.get_visible() and getattr(text, "_graphunslopify_text_target", {}).get("role") == "title"), default=0)
        required_height = sum(row_heights.values()) + title_height + fig.dpi * 0.3
        if row_heights and required_height > fig.bbox.height + 1:
            fig.set_size_inches(fig.get_figwidth(), required_height / fig.dpi)
        fig.tight_layout()


def decorate_panel(ax, frame, panel_label, show_x=True, show_y=True):
    if show_x:
        ax.set_xlabel("Learning rate")
        edit_target(ax.xaxis.label, ["x", "label"], "axis_label", "learning_rate")
    if show_y:
        ax.set_ylabel("Batch size")
        edit_target(ax.yaxis.label, ["y", "label"], "axis_label", "batch_size")
    ax.grid(False)
    if panel_label is not None:
        mark_panel_text(ax.set_title(str(panel_label), loc="left", fontsize=PANEL_LETTER_PT), CURRENT_PANEL)


def add_legend(fig, ax, frame, layout_columns=None):
    return


def describe_figure(frame):
    """Levels 2 and 3 of the alt text: the numbers and the trend."""
    parts = []
    if SAMPLE_SIZE_TEXT:
        parts.append(SAMPLE_SIZE_TEXT)
    matrix = heatmap_matrix(frame)
    values = matrix.to_numpy(dtype=float)
    if np.isfinite(values).any():
        row, column = np.unravel_index(np.nanargmax(values), values.shape)
        parts.append(f"Values run from {np.nanmin(values):.3g} to {np.nanmax(values):.3g}")
        parts.append(f"the largest is {values[row,column]:.3g} at {matrix.columns[column]}, {matrix.index[row]}")
    if not parts:
        return ""
    # Every clause is its own sentence, so a screen reader pauses between them.
    return ". ".join(part[:1].upper() + part[1:] for part in parts) + "."


def check(fig):
    # Optional. Install graphunslopify for readability and colour checks.
    try:
        from graphunslopify import inspect_figure
    except ImportError:
        print("graphunslopify not installed, skipping figure checks")
        RUN_REPORT["inspection"] = {"available": False, "checked": False}
        finding("warning", "inspection_unavailable", "Install graphunslopify to run figure inspection")
        return True
    paths = [item["path"] for item in RUN_REPORT["outputs"] if item["format"] in {"png", "svg", "pdf"}]
    report = None
    try:
        report = inspect_figure(fig, target_width_in=TARGET_WIDTH_IN, min_text_pt=MIN_TEXT_PT, export_paths=paths)
    except TypeError as error:
        if "export_paths" not in str(error): raise
    if report is None or not getattr(report, "measurements", None) or report.measurements.get("basis") not in {"exports", "unavailable"} or "data_view" not in report.measurements:
        RUN_REPORT["inspection"] = {"available": True, "checked": False}
        finding("warning", "inspection_outdated", "Upgrade graphunslopify: final exported text-size or data-view inspection is unavailable in this checker")
        return False
    print(f"figure checks: {len(report.findings)} finding(s)" if "_execution_policy" in RUN_REPORT else report)
    RUN_REPORT["inspection"] = {"available": True, "checked": report.measurements["basis"] == "exports", "measurements": report.measurements}
    for item in report.findings:
        finding(item.severity, item.code, item.message)
        if item.code == "cell_text_contrast_untested":
            RUN_REPORT["untested"].append(item.message)
    return report.ok


def panels(df):
    """One entry per panel. Without faceting that is the whole frame."""
    return [(None, df)]


SHARE_X = False
SHARE_Y = False
FACET_COLUMNS = 1


def main():
    global DATA_HASH, ALT_TEXT
    df = prepare(load())
    report_counts(df)
    validate_legend_aliases(df)
    if PALETTE_LOCK is not None and GROUP is not None:
        globals()["LOCKED"] = locked_appearance(
            SERIES_ORDER if SERIES_ORDER is not None else sorted(df[GROUP].dropna().unique(), key=str)
        )
    blocks = panels(df)
    if not blocks: raise ValueError("no usable facet values in the prepared data")
    globals()["PANEL_ORIGINAL_NAMES"] = [name for name, _ in blocks]
    validate_panel_aliases(df, blocks)
    columns = min(FACET_COLUMNS, len(blocks)) if len(blocks) > 1 else 1
    rows = math.ceil(len(blocks) / columns)

    with plt.rc_context(RC_PARAMS):
        fig, axes = plt.subplots(
            rows,
            columns,
            figsize=(FIGSIZE[0], FIGSIZE[1] * rows) if rows > 1 else FIGSIZE,
            sharex=SHARE_X,
            sharey=SHARE_Y,
            squeeze=False,
        )
        flat = list(axes.flat)
        legend_added = False
        for index, (name, block) in enumerate(blocks):
            ax = flat[index]
            globals()["CURRENT_PANEL"] = index
            if block.empty:
                ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center")
                mark_panel_text(ax.set_title(panel_label_value(index, name)), index)
                ax.set_axis_off()
                continue

            draw_panel(ax, block)


            letter = panel_label_value(index, name) if name is not None else None
            show_x = (index // columns) == rows - 1 or not SHARE_X
            show_y = (index % columns) == 0 or not SHARE_Y
            decorate_panel(ax, block, letter, show_x, show_y)
            # One legend for the whole figure; repeating it wastes panel space.
            if not legend_added:
                add_legend(fig, ax, block)
                legend_added = True
        for spare in flat[len(blocks) :]:
            spare.set_visible(False)

        if len(blocks) > 1:
            edit_target(fig.suptitle("Hyperparameter sweep"), ["title"], "title")
        else:
            edit_target(flat[0].set_title("Hyperparameter sweep"), ["title"], "title")
        fit_headings(fig)
        fit_category_labels(fig, flat)
        fig.tight_layout()
        fit_headings(fig)
        description = disclose_panel_aliases(disclose_legend_aliases(describe_panels(blocks)))
        claims_hold = not any(c["verdict"] == "fails" for c in RUN_REPORT["claims"])
        print(f"alt text: {description}")
        ALT_TEXT = description
        capture_environment(fig)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            meta = metadata_for(fmt)
            fig.savefig(path, bbox_inches="tight", metadata=meta, **({"dpi": DPI} if fmt == "png" else {}))
            record_output(path)
            print(f"wrote {path}")
        check(fig)
    plt.close(fig)


    print(DISCLOSURE)
    print(f"data sha256:{DATA_HASH}")
    if not claims_hold:
        print("at least one claim failed. The caption must not assert it.")


if __name__ == "__main__":
    raise SystemExit(run_cli())
